diff --git a/build/noprogress.go b/build/noprogress.go
index 16a33c4..2267af2 100644
--- a/build/noprogress.go
+++ b/build/noprogress.go
@@ -186,6 +186,11 @@ func (b *Attempt) noEditRound(stage string) (feedback string, check bool, err er
 		b.s.Progress("kogen: round " + itoa(b.Round) + " made no edits")
 		return "", true, nil
 	}
+	if redEnvironmental(red.pass) {
+		b.s.Progress("kogen: round " + itoa(b.Round) + " made no edits; verification pass " + itoa(red.pass.N) +
+			" failed with an environment failure, so the tree is verified again")
+		return "", true, nil
+	}
 	pass := red.pass
 	if red.noticeRound == 0 {
 		red.noticeRound = b.Round
@@ -208,6 +213,25 @@ func (b *Attempt) noEditRound(stage string) (feedback string, check bool, err er
 	return "", false, e
 }

+// redEnvironmental reports whether a failing check of the red pass has an environment failure
+// of a known kind (timeout, disk, memory or files): the builder cannot edit toward such a line,
+// so the unchanged tree is verified again and the host-or-base rule compares the two passes.
+func redEnvironmental(pass verify.Pass) bool {
+	failing := map[string]bool{}
+	for _, name := range pass.Failing {
+		failing[name] = true
+	}
+	for _, r := range pass.Checks {
+		if !failing[r.Name] {
+			continue
+		}
+		if line, ok := verify.EnvFailure(r); ok && envFailureKind(line) != "other" {
+			return true
+		}
+	}
+	return false
+}
+
 // missingAcceptanceItems are the expected scenarios of the pass's acceptance that did not pass,
 // in feature order, each as `<status>: <name> (line <line>)`. A pass whose acceptance did not
 // run has none.

